INSERT INTO `sys_news` VALUES
(1,0,1643192235,1604674724,0,0,0,0,'Welcome to the TYPO3 Demo Project','<p>With our TYPO3 Demo Project you get the chance to experience TYPO3\'s many amazing features!</p>\r\n<p>Take a look at the CMS as an FAQ-Editor or Advanced Editor and feel free to edit whatever you like.<br /> Choose a random username and the user role you would like to try outâ€”and there you go!</p>\r\n<p><strong>For Developers</strong><br /> The Demo Project is publicly available on <a href=\"https://gitlab.typo3.org\" target=\"_blank\">GitLab</a>. Check it out!</p>');
